const path = require('path');

const migrationsDir = './migrations';
const envPath = './.env.test';

// Read and parse .env.test file manually
fs.readFile(envPath, 'utf8', (err, data) => {
  if (err) {
    console.error('Error reading .env.test file:', err);
    return;
  }

  // Extract DATABASE_URL
  const dbUrlMatch = data.match(/^DATABASE_URL=(.+)/m);
  const dbUrl = dbUrlMatch ? dbUrlMatch[1].trim() : null;

  if (!dbUrl) {
    console.error('DATABASE_URL not found in .env.test');
    return;
  }

  // Log successful 'connection'
  console.log(`Connected to database: ${dbUrl}`);
  console.log(); // Add a blank line for readability

  // Now read and process migration files
  fs.readdir(migrationsDir, (err, files) => {
    if (err) {
      if (err.code === 'ENOENT') {
        console.log('Migrations directory does not exist.');
      } else {
        console.error('Error reading migrations directory:', err);
      }
      return;
    }

    // Filter only .sql files and sort them alphabetically
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in the directory.');
      return;
    }

    // Log each migration file that would be applied
    console.log('Applying migrations:');
    sqlFiles.forEach(file => {
      console.log(`- ${file}`);
    });
  });
});

