const fs = require('fs');
const path = require('path');

// Simple dotenv parser (no external dependency)
function loadEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const env = {};
    content.split(/\r?\n/).forEach(line => {
      // Match KEY=VALUE lines, handling values with = signs
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();
        // Remove surrounding quotes if present
        if (/^(['"])(.*)\\1$/.test(value)) {
          value = value.slice(1, -1);
        }
        env[key] = value;
      }
    });
    return env;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.log(`.env file not found: ${filePath}`);
      return {};
    }
    throw err;
  }
}

const migrationsDir = path.resolve('./migrations');
const env = loadEnvFile('.env.test');
const databaseUrl = env.DATABASE_URL;

if (!databaseUrl) {
  console.log('DATABASE_URL not found in .env.test');
} else {
  console.log(`Connecting to database using: ${databaseUrl}`);
  console.log('Connected successfully.\n');
}

// Read and sort migration files
